import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on effect size and statistical significance
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now
        t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
        p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 1))
        if p_val < 0.05 and abs(t_stat) > 3:
            effects.append((fid, abs(t_stat)))

    # Sort by effect size
    effects.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates, avoiding near-duplicates
    selected = []
    used_ids = set()
    for fid, _ in effects:
        if len(selected) >= MAX_DRIVERS:
            break
        # Check correlation with already selected features
        is_duplicate = False
        for sel_fid in selected:
            col_a = feats.column(sel_fid)
            col_b = feats.column(fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]) > 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            selected.append(fid)
            used_ids.add(fid)

    # If no strong drivers found, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Limit to at most 4 drivers as per checker report
    if len(selected) > 4:
        selected = selected[:4]

    # Build regression components
    drivers = tuple(selected)
    columns = tuple(selected)

    # Add interaction terms for top features
    products = []
    for i in range(len(selected)):
        for j in range(i+1, len(selected)):
            products.append((selected[i], selected[j]))

    # Create weighted score using top features
    loadings = {}
    for i, fid in enumerate(selected):
        loadings[fid] = np.abs(np.corrcoef(feats.x[:, feats.column(fid)], feats.y)[0, 1])

    # Normalize loadings
    total = sum(loadings.values())
    if total > 0:
        for fid in loadings:
            loadings[fid] /= total

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

